'use strict';
const WORTitles=(()=>{
 let starting=false,saveTimer,removed=null;const polling=new Set();
 const labels={clarity:'Clarté',hook:'Intérêt & curiosité',specificity:'Précision',audienceFit:'Adéquation au public',credibility:'Crédibilité'};
 function lab(){return ep().titleLab??={schema:1,candidates:[{id:uid(),title:ep().lab?.commonTitle||ep().youtubeTitle||''},{id:uid(),title:''}],brief:ep().lab?.brief||ep().subject||'',change:0,topCount:3,reports:[],pending:null,selection:[]}}
 const current=()=>{const l=lab(),r=l.reports.at(-1);return r&&r.change===l.change&&JSON.stringify(r.audience)===JSON.stringify(WORLab.audience())?r:null};
 const entries=()=>lab().candidates.filter(c=>c.title.trim());
 async function api(route,body){if(!server)throw Error('Ouvre le studio avec son lanceur local pour analyser les titres.');const res=await fetch('/api/lab/'+route,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-WOR-Token':token},body:JSON.stringify(body)});const data=await res.json();if(!res.ok)throw Error(data.error||'Analyse indisponible.');return data}
 function results(){const r=current();if(!r)return '<section class="lab-empty-report"><h3>Quel titre donne envie de regarder ?</h3><p>Compare au moins deux formulations. Le prétest expliquera leurs forces et les points à retravailler.</p></section>';const l=lab(),all=r.job.result.ranking,rows=l.showAll?all:all.slice(0,WORPretest.count(l));return `<section class="lab-report"><div class="section-head"><div><span class="meta-caps">TES TITRES · ${fmt(r.job.completed)}</span><h2>Ton top ${Math.min(WORPretest.count(l),all.length)}</h2><p>${esc(r.job.result.summary)}</p></div><button class="button" id="title-pick-top">Garder ce top</button></div><div class="title-rankings">${rows.map(row=>{const c=r.job.input.candidates.find(c=>c.id===row.id);return `<article class="title-result"><span class="rank-position">${all.findIndex(x=>x.score===row.score)+1}</span><div><h3>${esc(c.title)}</h3><p>${esc(row.rationale)}</p><details><summary>Pourquoi ce titre ?</summary><div class="lab-criteria">${Object.entries(row.scores).map(([k,n])=>`<div><span>${labels[k]}</span><b>${n===null?'Non évalué':n+'/5'}</b></div>`).join('')}</div><h4>Points forts</h4><ul>${row.strengths.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h4>À retravailler</h4><ul>${row.improvements.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>${esc(row.evidenceLimit)}</p></details><div class="title-result-actions"><button class="button small ${l.selection.includes(c.id)?'green':''}" data-title-pick="${esc(c.id)}">${l.selection.includes(c.id)?'✓ Dans ma sélection':'Garder ce titre'}</button><button class="text-button" data-title-use="${esc(c.id)}">Utiliser avec mes miniatures ↗</button></div></div><strong class="rank-score">${row.score}<small>/100</small></strong></article>`}).join('')}</div><p class="muted">${r.job.result.limitations.map(esc).join(' · ')}</p>${all.length>WORPretest.count(l)?`<button class="button" id="title-show-all">${l.showAll?'Réduire au top':'Voir tous les titres'}</button>`:''}</section>`}
 function renderTitles(){const l=lab(),n=entries().length;return head('LE PRÉTEST WOR','Le bon titre fait la différence.','Compare tes formulations et garde les 3 ou 5 pistes les plus convaincantes.')+episodeLine()+WORPretest.tabs('titles')+`<section class="panel title-intake"><div class="section-head"><div><span class="meta-caps">01 · TES FORMULATIONS</span><h2>Un épisode. Plusieurs accroches.</h2><p>Jusqu’à 20 titres, sans image à importer. ${n} titre(s) renseigné(s).</p></div><button class="button" id="title-bulk">Coller une liste</button></div><div class="title-inputs">${l.candidates.map((c,i)=>`<div class="title-input-row"><label for="title-${c.id}">${String(i+1).padStart(2,'0')}</label><input id="title-${c.id}" data-title-id="${c.id}" aria-label="Titre ${i+1}" maxlength="200" placeholder="Écris une formulation…" value="${esc(c.title)}"><button class="icon-button" data-title-remove="${c.id}" aria-label="Retirer le titre ${i+1}">×</button></div>`).join('')}</div><div class="title-add"><button class="button small" id="title-add" ${l.candidates.length>=20?'disabled':''}>＋ Ajouter un titre</button>${removed?.episode===ep().id?'<button class="text-button" id="title-undo">Rétablir le dernier titre</button>':''}</div><details class="title-context"><summary>Contexte de l’épisode</summary><label class="field">Sujet, contenu réel et promesses vérifiables<textarea id="title-brief" rows="3" maxlength="12000" placeholder="Le contexte permet de vérifier que les titres correspondent à la vidéo.">${esc(l.brief)}</textarea></label></details></section><section class="pretest-action panel"><div><span class="meta-caps">02 · COMPARER</span><h2>Les mots aussi se testent.</h2><p>Clarté, intérêt, précision, crédibilité et adéquation au public. Les titres sont évalués seuls, sans prétendre analyser une miniature.</p><p class="muted">Le contexte et les titres sont envoyés à OpenAI via ton compte Codex. Une présélection IA, pas un test auprès de spectateurs.</p></div><div class="pretest-controls"><label class="field">Ma présélection<select id="title-top"><option value="3" ${WORPretest.count(l)===3?'selected':''}>Top 3</option><option value="5" ${WORPretest.count(l)===5?'selected':''}>Top 5</option></select></label><button class="button primary" id="title-analyze" ${l.pending||n<2?'disabled':''}>${l.pending?'Analyse en cours…':current()?'Revoir le classement':'Lancer le prétest des titres →'}</button></div></section>${l.pending?'<div class="lab-running" role="status">Analyse des titres en cours. Tu peux changer d’onglet ; le rapport sera conservé.<div class="progress"><div></div></div></div>':''}${l.lastError?`<p class="inline-note">${esc(l.lastError)}</p>`:''}<div id="title-results">${results()}</div><section class="panel lab-export"><div><h2>Ta sélection de titres</h2><p>Jusqu’à cinq pistes à partager ou à retravailler.</p><span class="badge">${l.selection.length}/5 sélectionnées</span></div><div><button class="button" id="title-export" ${l.selection.length?'':'disabled'}>↓ Exporter mes titres</button><button class="text-button" id="title-report" ${l.reports.length?'':'disabled'}>↓ Rapport de présélection</button></div></section>`}
 function changed(){const l=lab();l.change++;clearTimeout(saveTimer);saveTimer=setTimeout(()=>persist(),300);const b=$('#title-analyze');if(b){b.textContent=l.pending?'Analyse en cours…':'Lancer le prétest des titres →';b.disabled=!!l.pending||entries().length<2}$('#title-results').innerHTML=results()}
 async function analyze(){const l=lab();if(starting||l.pending)return;if(current())return $('#title-results').scrollIntoView({behavior:'smooth'});const candidates=entries().map(c=>({...c,title:c.title.trim()}));if(candidates.length<2)return toast('Ajoute au moins deux titres.');const unique=new Set(candidates.map(c=>c.title.normalize('NFKC').toLowerCase().replace(/\s+/g,' ')));if(unique.size!==candidates.length)return toast('Deux titres sont identiques. Garde des formulations différentes.');starting=true;const episode=ep().id,profile=structuredClone(WORLab.audience());l.pending={id:null,change:l.change,audience:profile};l.lastError=null;
  try{await persist();render();const job=await api('analyze',{mode:'titles',brief:l.brief,audience:profile,candidates});l.pending.id=job.id;await persist();if(job.status==='complete')await finish(episode,job);else poll(episode,job.id)}catch(e){l.pending=null;l.lastError=e.message;await persist()}finally{starting=false;if(view==='titles')render()}
 }
 async function finish(episode,job){const l=state.episodes.find(e=>e.id===episode)?.titleLab;if(!l)return;const pending=l.pending;if(job.status==='complete'){if(!l.reports.some(r=>r.job.id===job.id))l.reports.push({job,change:pending?.change??l.change,audience:pending?.audience??structuredClone(WORLab.audience())});l.lastError=null}else l.lastError=job.error||'Analyse interrompue.';l.pending=null;await persist();if(view==='titles'&&ep().id===episode)render()}
 async function poll(episode,id){if(polling.has(id))return;polling.add(id);try{for(;;){const job=await api('job?id='+encodeURIComponent(id));if(job.status!=='running'){await finish(episode,job);break}await new Promise(r=>setTimeout(r,2200))}}catch(e){const l=state.episodes.find(e=>e.id===episode)?.titleLab;if(l){l.lastError='Recharge la page pour reprendre le suivi : '+e.message;await persist()}if(view==='titles')render()}finally{polling.delete(id)}}
 function bulk(){form('<div class="dialog-top"><h2>Coller plusieurs titres</h2><button class="icon-button" id="close-form" aria-label="Fermer">×</button></div><p>Un titre par ligne. Ils seront ajoutés à ta liste ; les doublons exacts seront ignorés.</p><label class="field">Liste des titres<textarea id="title-list" rows="8" maxlength="5000" placeholder="Premier titre\nDeuxième titre\nTroisième titre"></textarea></label><button class="button primary full" id="title-import">Ajouter les titres</button>');on('title-import',async()=>{const l=lab(),existing=new Set(entries().map(c=>c.title.trim())),lines=[...new Set($('#title-list').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean))].filter(x=>!existing.has(x));if(!lines.length)return toast('Aucun nouveau titre.');if(lines.some(x=>x.length>200))return toast('Chaque titre est limité à 200 caractères.');if(entries().length+lines.length>20)return toast('Maximum : 20 titres.');l.candidates=l.candidates.filter(c=>c.title.trim()).concat(lines.map(title=>({id:uid(),title})));l.change++;await persist();$('#form-dialog').close();render()})}
 function wire(){const l=lab();WORPretest.wireTabs();on('title-bulk',bulk);on('title-analyze',analyze);on('title-add',async()=>{if(l.candidates.length>=20)return;l.candidates.push({id:uid(),title:''});changed();await persist();render();$$('[data-title-id]').at(-1)?.focus()});on('title-undo',async()=>{if(!removed||removed.episode!==ep().id||l.candidates.length>=20)return;l.candidates.splice(removed.index,0,removed.candidate);removed=null;changed();await persist();render()});
  $$('[data-title-id]').forEach(el=>el.oninput=()=>{l.candidates.find(c=>c.id===el.dataset.titleId).title=el.value;changed()});$$('[data-title-remove]').forEach(el=>el.onclick=async()=>{const i=l.candidates.findIndex(c=>c.id===el.dataset.titleRemove);removed={episode:ep().id,index:i,candidate:l.candidates[i]};l.candidates.splice(i,1);l.selection=l.selection.filter(id=>id!==el.dataset.titleRemove);changed();await persist();render()});
  $('#title-brief').oninput=e=>{l.brief=e.target.value;changed()};$('#title-top').onchange=async e=>{l.topCount=Number(e.target.value);await persist();render()};on('title-show-all',async()=>{l.showAll=!l.showAll;await persist();render()});on('title-pick-top',async()=>{if(!current())return;l.selection=current().job.result.ranking.slice(0,WORPretest.count(l)).map(c=>c.id);await persist();render()});
  $$('[data-title-pick]').forEach(el=>el.onclick=async()=>{const id=el.dataset.titlePick;if(l.selection.includes(id))l.selection=l.selection.filter(x=>x!==id);else{if(l.selection.length>=5)return toast('Maximum : cinq titres sélectionnés.');l.selection.push(id)}await persist();render()});
  $$('[data-title-use]').forEach(el=>el.onclick=async()=>{if(!current())return;const text=l.candidates.find(c=>c.id===el.dataset.titleUse).title,images=WORLab.getLab();images.commonTitle=text;images.titleMode='common';images.change++;ep().youtubeTitle=text;await persist();navigate('ab');toast('Titre appliqué aux miniatures. Leur prétest est à actualiser.')});
  on('title-export',()=>download(l.candidates.filter(c=>l.selection.includes(c.id)).map(c=>c.title).join('\n'),`WOR_${safe(ep().name)}_Titres.txt`,'text/plain'));on('title-report',()=>download(JSON.stringify({episode:ep().name,report:l.reports.at(-1),stale:!current(),selection:l.selection,top:WORPretest.count(l),note:'Évaluation des titres seuls ; aucune mesure de clics.'},null,2),`WOR_${safe(ep().name)}_Pretest_titres.json`,'application/json'));
  if(l.pending?.id)poll(ep().id,l.pending.id);else if(l.pending&&!starting){l.pending=null;l.lastError='Demande interrompue avant réception de son identifiant. Aucun nouvel appel automatique.'}
 }
 return {render:renderTitles,wire,current};
})();
